// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListHouseholds 所属するすべての世帯を、自分のロールとともに返す
	// (GET /households)
	ListHouseholds(ctx context.Context, request ListHouseholdsRequestObject) (ListHouseholdsResponseObject, error)
	// CreateHousehold 世帯を作成し、作成したユーザーをオーナーにする
	// (POST /households)
	CreateHousehold(ctx context.Context, request CreateHouseholdRequestObject) (CreateHouseholdResponseObject, error)
	// DeleteHousehold 世帯を削除する（オーナーのみ）
	// (DELETE /households/{householdId})
	DeleteHousehold(ctx context.Context, request DeleteHouseholdRequestObject) (DeleteHouseholdResponseObject, error)
	// UpdateHousehold 世帯名・地域を変更する（オーナーのみ）
	// (PATCH /households/{householdId})
	UpdateHousehold(ctx context.Context, request UpdateHouseholdRequestObject) (UpdateHouseholdResponseObject, error)
	// ListInvitations 有効な招待の一覧（オーナーのみ）
	// (GET /households/{householdId}/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// CreateInvitation 招待を作成する（オーナーのみ）
	// (POST /households/{householdId}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// RevokeInvitation 招待を取り消す（オーナーのみ）
	// (DELETE /households/{householdId}/invitations/{invitationId})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// ListMembers 世帯のメンバーの一覧
	// (GET /households/{householdId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// GetNotificationSettings この世帯での自分の通知設定を取得する
	// (GET /households/{householdId}/members/me/notification-settings)
	GetNotificationSettings(ctx context.Context, request GetNotificationSettingsRequestObject) (GetNotificationSettingsResponseObject, error)
	// UpdateNotificationSettings この世帯での自分の通知設定を変更する（閲覧者も変更できる）
	// (PUT /households/{householdId}/members/me/notification-settings)
	UpdateNotificationSettings(ctx context.Context, request UpdateNotificationSettingsRequestObject) (UpdateNotificationSettingsResponseObject, error)
	// RemoveMember メンバーを世帯から外す（自分なら退出）
	// (DELETE /households/{householdId}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMemberRole メンバーのロールを変更する（オーナーのみ）
	// (PATCH /households/{householdId}/members/{userId})
	UpdateMemberRole(ctx context.Context, request UpdateMemberRoleRequestObject) (UpdateMemberRoleResponseObject, error)
	// TransferOwnership オーナー権限を別のメンバーに移す（オーナーのみ）
	// (POST /households/{householdId}/ownership-transfer)
	TransferOwnership(ctx context.Context, request TransferOwnershipRequestObject) (TransferOwnershipResponseObject, error)
	// GetInvitation 招待の内容（世帯名と付与されるロール）を取得する
	// (GET /invitations/{tokenOrCode})
	GetInvitation(ctx context.Context, request GetInvitationRequestObject) (GetInvitationResponseObject, error)
	// AcceptInvitation 招待を受けて、世帯に参加する
	// (POST /invitations/{tokenOrCode}/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// GetMe 自分のプロフィールを取得する
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe 自分の表示名を変更する
	// (PUT /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// RegisterDevice プッシュ通知の送信先となる端末を登録・更新する
	// (POST /me/devices)
	RegisterDevice(ctx context.Context, request RegisterDeviceRequestObject) (RegisterDeviceResponseObject, error)
	// UnregisterDevice 端末をプッシュ通知の送信先から外す
	// (DELETE /me/devices/{deviceId})
	UnregisterDevice(ctx context.Context, request UnregisterDeviceRequestObject) (UnregisterDeviceResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

